import os, sys, glob, json
try:
    import zstandard as zstd
except ImportError:
    print("NO_ZSTD_MODULE"); sys.exit(0)

root = r"C:\Users\Administrator\.dsh\sessions"
pats = ["不再发浏览器命令", "回复「继续」"]
hits = []
files = []
for d in glob.glob(os.path.join(root, "*")):
    if not os.path.isdir(d): continue
    files += glob.glob(os.path.join(d, "*", "session*.jsonl.zstd"))
print(f"scanning {len(files)} session archives")
for fp in files:
    if os.path.getmtime(fp) < (time.time() - 14*86400) if False else False:
        continue
    try:
        with open(fp, "rb") as fh:
            data = zstd.ZstdDecompressor().stream_reader(fh).read()
        text = data.decode("utf-8", errors="ignore")
        for p in pats:
            if p in text:
                idx = text.find(p)
                ctx = text[max(0,idx-300):idx+200].replace("\n", "\\n")
                hits.append((fp, p, ctx))
    except Exception as e:
        pass
print(f"HITS: {len(hits)}")
for fp, p, ctx in hits[:10]:
    print("=" * 40)
    print(fp)
    print(f"pattern={p}")
    print(ctx[:500])

import os, sys, glob, io, json
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
import zstandard as zstd

fp = r"C:\Users\Administrator\.dsh\sessions\--D-repository-~82CF~4F4F~623FG--\session-f37f8e2c-a0e2-4eb1-8285-554edd02494e\session.v4.jsonl.zstd"
with open(fp, "rb") as fh:
    data = zstd.ZstdDecompressor().stream_reader(fh).read()
text = data.decode("utf-8", errors="ignore")

for lineno, line in enumerate(text.split("\n"), 1):
    if "不再发浏览器命令" not in line:
        continue
    line = line.strip()
    if not line:
        continue
    print("=" * 60)
    print(f"line {lineno}, len={len(line)}")
    try:
        rec = json.loads(line)
        print("type:", rec.get("type"))
        print("seq:", rec.get("seq"), "time:", rec.get("time"))
        d = rec.get("data") or {}
        src = d.get("source") or {}
        print("data.source:", json.dumps(src, ensure_ascii=False)[:300])
        ins = d.get("inserted") or []
        for item in ins:
            i_src = item.get("source") or {}
            print("  inserted.source.kind:", i_src.get("kind"), "| plugin:", i_src.get("plugin"), "| rpcId:", i_src.get("rpcId"))
            for c in item.get("content") or []:
                t = c.get("text", "")
                i = t.find("不再发浏览器命令")
                if i >= 0:
                    print("  TEXT[-300:+400]:", t[max(0, i-300):i+400].replace("\n", "\\n"))
    except Exception as e:
        i = line.find("不再发浏览器命令")
        print("RAW[-400:+400]:", line[max(0,i-400):i+400])

